using Xunit;

public class SymptomTest
{
    [Fact]
    public void TC_001_AddNewSymptom()
    {
        // Arrange
        var symptomService = new SymptomService();
        var symptomName = "Cough";
        var symptomDescription = "Dry cough";

        // Act
        symptomService.AddSymptom(symptomName, symptomDescription);

        // Assert
        var symptom = symptomService.GetSymptomByName(symptomName);
        Assert.NotNull(symptom);
        Assert.Equal(symptomName, symptom.Name);
        Assert.Equal(symptomDescription, symptom.Description);
    }

    [Fact]
    public void TC_002_ViewAndUpdateSymptom()
    {
        // Arrange
        var symptomService = new SymptomService();
        var symptomName = "Cough";
        var symptomDescription = "Dry cough";
        symptomService.AddSymptom(symptomName, symptomDescription);

        var updatedDescription = "Dry cough with phlegm";

        // Act
        symptomService.UpdateSymptom(symptomName, updatedDescription);

        // Assert
        var symptom = symptomService.GetSymptomByName(symptomName);
        Assert.NotNull(symptom);
        Assert.Equal(symptomName, symptom.Name);
        Assert.Equal(updatedDescription, symptom.Description);
    }

    [Fact]
    public void TC_003_DeleteSymptom()
    {
        // Arrange
        var symptomService = new SymptomService();
        var symptomName = "Cough";
        var symptomDescription = "Dry cough";
        symptomService.AddSymptom(symptomName, symptomDescription);

        // Act
        symptomService.DeleteSymptom(symptomName);

        // Assert
        var symptom = symptomService.GetSymptomByName(symptomName);
        Assert.Null(symptom);
    }

    [Fact]
    public void TC_004_DeleteSymptomWithConsultationRequest()
    {
        // Arrange
        var symptomService = new SymptomService();
        var consultationService = new ConsultationService();
        var symptomName = "Cough";
        var symptomDescription = "Dry cough";
        symptomService.AddSymptom(symptomName, symptomDescription);

        var consultation = new Consultation { Symptom = symptomService.GetSymptomByName(symptomName) };
        consultationService.AddConsultation(consultation);

        // Act & Assert
        Assert.Throws<InvalidOperationException>(() => symptomService.DeleteSymptom(symptomName));
    }

    [Fact]
    public void TC_005_DeleteSymptomWithMultipleConsultationRequests()
    {
        // Arrange
        var symptomService = new SymptomService();
        var consultationService = new ConsultationService();
        var symptomName = "Cough";
        var symptomDescription = "Dry cough";
        symptomService.AddSymptom(symptomName, symptomDescription);

        var consultation1 = new Consultation { Symptom = symptomService.GetSymptomByName(symptomName) };
        var consultation2 = new Consultation { Symptom = symptomService.GetSymptomByName(symptomName) };
        consultationService.AddConsultation(consultation1);
        consultationService.AddConsultation(consultation2);

        // Act & Assert
        Assert.Throws<InvalidOperationException>(() => symptomService.DeleteSymptom(symptomName));
    }
}
